#include<bits/stdc++.h>
#define int long long
using namespace std;
int f[555555],d[555555],d1[555555];
vector<int>v[555555],v1[555555];
int dp[555555][22],dp1[555555][22];
int a[555555];
int n,q;
int ff(int a,int b){
    if (b==0){
        return 1;
    }
    int h=ff(a,b/2);
    int x=h*h;
    if (b%2==1) {
        x*=a;
	}
    return x; 
}
void dfs(int p,int g,int fa){
	d[p]=g;
	dp[p][0]=fa;
	for(int i=1;i<=20;i++){
		dp[p][i]=dp[dp[p][i-1]][i-1];
	} 
	int mn=n+1;
	for(int i=0;i<v[p].size();i++){
		if(v[p][i]!=fa){
			f[v[p][i]]=p;
			dfs(v[p][i],g+1,p);
			mn=min(mn,v[p][i]);
		}
	}
	if(mn==n+1){
		dp1[p][0]=p;
		for(int i=1;i<=20;i++){
			dp1[p][i]=p;
		} 
	}else{
		dp1[p][0]=mn;
		for(int i=1;i<=20;i++){
			dp1[p][i]=dp1[dp1[p][i-1]][i-1];
		} 
	}
}
