		for(int i=1;i<=y;i++){
			cin>>a[i];
			if(a[i]>0){
				for(int j=20;j>=0;j--){
					if(ff(2,j)<=a[i]){
						x=dp[x][j];
						a[i]-=ff(2,j);
					}
				}
			}else{
				a[i]=abs(a[i]);
